INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(45211, 'Jeremiah 51:43', 'Jeremiah', 51, 43, 'د هغۀ ښارونه به وران او تباه کړى او په اوچه دشته او ميره باندې به بدل شى، هغه به په داسې زمکه باندې بدل شى چې څوک به هم په کښې نۀ اوسيږى، او نۀ به څوک په کښې سفر کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_43.mp3', '', 1761754199, 1761754199),
(45212, 'Jeremiah 51:44', 'Jeremiah', 51, 44, 'زۀ به د بابل معبود بيل بُت ته سزا ورکړم، او څۀ چې يې خوړلى دى هغه به پرې ګنډير کړم. قومونه به نور د هغۀ عبادت نۀ کوى. او د بابل دېوالونه به راوغورزيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_44.mp3', '', 1761754199, 1761754199),
(45213, 'Jeremiah 51:45', 'Jeremiah', 51, 45, 'اے زما خلقو د هغۀ نه رابهر شئ. د خپل ژوند د بچ کولو دپاره د هغه ځائ نه منډه کړئ. او د مالِک خُدائ د سخت غضب نه وتښتئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_45.mp3', '', 1761754199, 1761754199),
(45214, 'Jeremiah 51:46', 'Jeremiah', 51, 46, 'تاسو چې په دغه مُلک کومې افواه ګانې اورئ نو چې د هغې په وجه نۀ بې‌زړۀ شئ او نۀ ويرېږئ. دا افواه به کال په کال راځى. ظلم او فساد به مُلک کښې راوچت شى او بادشاهان به د يو بل سره جنګونه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_46.mp3', '', 1761754199, 1761754199),
(45215, 'Jeremiah 51:47', 'Jeremiah', 51, 47, 'خو په حقيقت کښې هغه وخت راروان دے چې زۀ به د بابليانو بُتانو ته سزا ورکړم، او د هغۀ ټول مُلک به وشرميږى، او د هغوئ قتل شوى کسان به ټول په کښې مړۀ پراتۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_47.mp3', '', 1761754199, 1761754199),
(45216, 'Jeremiah 51:48', 'Jeremiah', 51, 48, 'نو بيا به آسمان او زمکه او هر څۀ چې په کښې دى د بابل په شکست د خوشحالۍ چغې ووهى، ځکه چې د شمال نه به تباه کوونکى فوجيان په هغۀ حمله وکړى، دا د مالِک خُدائ فرمان دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_48.mp3', '', 1761754199, 1761754199),
(45217, 'Jeremiah 51:49', 'Jeremiah', 51, 49, 'لکه څنګه چې بابل د بنى اِسرائيلو او د ټولې دُنيا د قتل عام سبب جوړ شوے وو، نو بيا به هغه هم هغه شان قتل کړے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_49.mp3', '', 1761754199, 1761754199),
(45218, 'Jeremiah 51:50', 'Jeremiah', 51, 50, '”تاسو څوک چې د مرګ نه راتښتېدلى يئ، ودرېږئ مه، لاړ شئ. تاسو چې څومره هم لرې يئ نو مالِک خُدائ يادوئ. او د خپل کور يروشلم په حقله سوچ کوئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_50.mp3', '', 1761754199, 1761754199),
(45219, 'Jeremiah 51:51', 'Jeremiah', 51, 51, 'تاسو وايئ چې، ”مونږ په شرمونو وشرمېدو، او زمونږ بې‌عزتى وشوه او شرم مو په مخ راخور شوے دے، ځکه چې غېر مُلکيان د مالِک خُدائ په مقدس ځائ کښې راداخل شوى دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_51.mp3', '', 1761754199, 1761754199),
(45220, 'Jeremiah 51:52', 'Jeremiah', 51, 52, 'مالِک خُدائ فرمائى چې، ”هغه ورځې راروانې دى کله چې به زۀ د بابل بُتانو ته سزا ورکړم نو د هغوئ د زخمونو زبيرګى به ټول مُلک کښې اورېدلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_52.mp3', '', 1761754199, 1761754199),
(45221, 'Jeremiah 51:53', 'Jeremiah', 51, 53, 'کۀ بابليان آسمان ته هم وخېژى او هلته يوه مضبوطه قلعه جوړه کړى، نو زۀ به هلته هم دشمنان ورولېږم چې هغوئ چور کړى، مالِک خُدائ فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_53.mp3', '', 1761754199, 1761754199),
(45222, 'Jeremiah 51:54', 'Jeremiah', 51, 54, '”د ژړا آوازونه د بابل نه راځى، د لوئ تباهۍ آوازونه د بابليانو د زمکې نه اورېدلے کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_54.mp3', '', 1761754199, 1761754199),
(45223, 'Jeremiah 51:55', 'Jeremiah', 51, 55, 'مالِک خُدائ به بابل تباه کړى، او هغه به د هغوئ د شور نه ډک ښار خاموشه کړى، دشمن به لکه د اوبو د غضبناکو چپو په شان راروان وى او د هغوئ د آوازونو شور به اورېدلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_55.mp3', '', 1761754199, 1761754199),
(45224, 'Jeremiah 51:56', 'Jeremiah', 51, 56, 'تباه کوونکے به د بابل خلاف راشى، د هغوئ جنګى فوجيان به ونيولے شى او د هغوئ ليندې به ماتې کړے شى. ځکه چې مالِک خُدائ د انتقام اخستلو خُدائ پاک دے او هغه به پوره بدله ورکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_56.mp3', '', 1761754199, 1761754199),
(45225, 'Jeremiah 51:57', 'Jeremiah', 51, 57, 'زۀ به د هغۀ مشران او پوهان نشه کړم، د هغۀ حکمرانان، آفسران، او فوجيان به هم نشه کړم. هغوئ به د تل دپاره اودۀ شى او بيا به نۀ راپاڅى، دا د بادشاه فرمان دے د چا نوم چې مالِک خُدائ ربُ الافواج دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_57.mp3', '', 1761754199, 1761754199),
(45226, 'Jeremiah 51:58', 'Jeremiah', 51, 58, 'مالِک خُدائ ربُ الافواج داسې فرمائى چې، ”د بابل پيړ دېوالونه به هوار کړے شى او د هغۀ اوچتې دروازې به وسوزولے شى، نو خلقو يې خپل ځان ستړے کړو خو هيڅ فائده يې ونۀ کړه، د دې قوم ټول محنت صرف د اور دپاره خشاک دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_58.mp3', '', 1761754199, 1761754199),
(45227, 'Jeremiah 51:59', 'Jeremiah', 51, 59, 'يرمياه نبى دا پېغام د عملى آفسر سراياه د نيرياه زوئ يعنې د محسياه نمسې ته هغه وخت ورکړو کله چې هغه بابل ته د صدقياه د يهوداه بادشاه د حکومت په څلورم کال د هغۀ سره لاړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_59.mp3', '', 1761754199, 1761754199),
(45228, 'Jeremiah 51:60', 'Jeremiah', 51, 60, 'يرمياه د هغه ټولو افتونو د تفصيل په حقله چې په بابل باندې راتلونکى وُو په يو طومار کښې وليکل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_60.mp3', '', 1761754199, 1761754199),
(45229, 'Jeremiah 51:61', 'Jeremiah', 51, 61, 'هغۀ سراياه ته وفرمائيل، ”کله چې تۀ بابل ته ورسېږې نو تۀ دا ټول کلام په اوچت آواز سره خلقو ته ولوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_61.mp3', '', 1761754199, 1761754199),
(45230, 'Jeremiah 51:62', 'Jeremiah', 51, 62, 'نو بيا داسې وايه چې، اے مالِکه خُدايه، تا وفرمائيل چې تاسو به دا ځائ تباه کړئ، نو په دې کښې به نۀ انسان او نۀ ځناور اوسيږى، او دا به د تل دپاره وران ويجاړ پروت وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_62.mp3', '', 1761754199, 1761754199),
(45231, 'Jeremiah 51:63', 'Jeremiah', 51, 63, 'کله چې تۀ د دې طومار لوستل بند کړې، نو يو کاڼے ورپورې وتړه او د فرات د سيند په مينځ کښې يې وغورزوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_63.mp3', '', 1761754199, 1761754199),
(45232, 'Jeremiah 51:64', 'Jeremiah', 51, 64, 'نو بيا هغوئ ته ووايه چې، دغه شان به بابليان ډوب شى او هيڅکله به بيا راوچت نۀ شى د هغه افت په وجه کوم چې زۀ په دوئ نازلوم. نو د هغۀ خلق به راوغورزيږى.“ د يرمياه خبرې دلته په دې ځائ باندې ختمې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah51_verse_64.mp3', '', 1761754199, 1761754199),
(45233, 'Psalms 33:1', 'Psalms', 33, 1, 'ای نېکانو هغه کارونه چې څښتن کړي هغې دپاره ووهئ د خوشحالۍ چیغې مناسبه ده ستاینه د هغه د صادقانو دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_1.mp3', '', 1761754199, 1761754199),
(45234, 'Psalms 33:2', 'Psalms', 33, 2, 'وکړئ شکرونه د څښتن په وهلو د رباب هم ورته وغږوئ ساز په چنګ سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_2.mp3', '', 1761754199, 1761754199),
(45235, 'Psalms 33:3', 'Psalms', 33, 3, 'هغه ته ووایئ سندره نوې په ښو سازونو سره او لوړ اوازونو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_3.mp3', '', 1761754199, 1761754199),
(45236, 'Psalms 33:4', 'Psalms', 33, 4, 'د څښتن کلام رښتینی دی او سم دی ټول کارونه د هغه د باور وړ دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_4.mp3', '', 1761754199, 1761754199),
(45237, 'Psalms 33:5', 'Psalms', 33, 5, 'خوښوي څښتن نېکي او عدالت ده ځمکه ډکه د څښتن له تلپاتې مینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_5.mp3', '', 1761754199, 1761754199),
(45238, 'Psalms 33:6', 'Psalms', 33, 6, 'اسمانونه د څښتن په حکم جوړ شول په خبره یې د خولې لمر او سپوږمۍ او ستوري جوړ شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_6.mp3', '', 1761754199, 1761754199),
(45239, 'Psalms 33:7', 'Psalms', 33, 7, 'دریابونه یې په یو ځای کې راټول کړل کړل بحرونه هغه بند په لویو لویو ذخیرو کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_7.mp3', '', 1761754199, 1761754199),
(45240, 'Psalms 33:8', 'Psalms', 33, 8, 'پرېږدئ ټوله ځمکه د څښتن څخه په وېره شي پرېږدئ ټول خلک د نړۍ یې درناوی وکړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_8.mp3', '', 1761754199, 1761754199),
(45241, 'Psalms 33:9', 'Psalms', 33, 9, 'کله چې ده ورکړو فرمان نو دا دنیا شوه پیدا د ده په امر ټول شیان پیدا شول', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_9.mp3', '', 1761754199, 1761754199),
(45242, 'Psalms 33:10', 'Psalms', 33, 10, 'د قومونو پلانونه څښتن ورشنډوي نه پرېږدي هغوی چې کړي حاصل خپل مقصدونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_10.mp3', '', 1761754199, 1761754199),
(45243, 'Psalms 33:11', 'Psalms', 33, 11, 'خو تل ترتله کړي دوام د ده پلانونه ټولو نسلونو پورې وي به دوامدار یې مقصدونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_11.mp3', '', 1761754199, 1761754199),
(45244, 'Psalms 33:12', 'Psalms', 33, 12, 'چې خدای یې وي څښتن نو هغه قوم بختور دی چې خپل ځان ته یې غوره کړي هغه خلک بختور دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_12.mp3', '', 1761754199, 1761754199),
(45245, 'Psalms 33:13', 'Psalms', 33, 13, 'لاندې ګوري له اسمان ځینې څښتن ویني مونږ ټول انسانان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_13.mp3', '', 1761754199, 1761754199),
(45246, 'Psalms 33:14', 'Psalms', 33, 14, 'په اسمان کې له خپل تخت نه هغه څاري ټول اوسېدونکي د جهان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_14.mp3', '', 1761754199, 1761754199),
(45247, 'Psalms 33:15', 'Psalms', 33, 15, 'دی جوړوونکی د هغوی د ټولو زړونو هغه او هم خبر یې دی د ټولو عملونو هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_15.mp3', '', 1761754199, 1761754199),
(45248, 'Psalms 33:16', 'Psalms', 33, 16, 'په خپل قوي لښکر پاچا کامیابېدلی نه شي په خپل زیات ځواک سره عسکر روغ راوتلی نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_16.mp3', '', 1761754199, 1761754199),
(45249, 'Psalms 33:17', 'Psalms', 33, 17, 'څوک چې یقین لري په جنګي اس نو بری موندلی نه شي که زورور وي جنګي اس بیاهم څوک بچ کولای نه شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_17.mp3', '', 1761754199, 1761754199),
(45250, 'Psalms 33:18', 'Psalms', 33, 18, 'څښتن ساتي خپل نظر په هغو خلکو چې کړي وېره له هغه نه او څوک چې باور لري د هغه په تلپاتې مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_18.mp3', '', 1761754199, 1761754199),
(45251, 'Psalms 33:19', 'Psalms', 33, 19, 'هغه دوی ساتي له مرګي نه په وختونو د قحطۍ کې یې هم ساتي ژوندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_19.mp3', '', 1761754199, 1761754199),
(45252, 'Psalms 33:20', 'Psalms', 33, 20, 'مونږ یو په امید کې کړو څښتن ته انتظار دی مرستندوی زمونږ او زمونږ سپر دی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_20.mp3', '', 1761754199, 1761754199),
(45253, 'Psalms 33:21', 'Psalms', 33, 21, 'زمونږ زړونه دي خوشحال د ده په وجه ځکه مونږ کړو توکل د ده په پاک نامه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_21.mp3', '', 1761754199, 1761754199),
(45254, 'Psalms 33:22', 'Psalms', 33, 22, 'څنګه چې تاته دی زمونږ امید داسې دې ستا تلپاتې مینه وي زمونږه سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms33_verse_22.mp3', '', 1761754199, 1761754199),
(45255, 'Deuteronomy 26:1', 'Deuteronomy', 26, 1, 'کله چې تاسو هغه خاوره ونیسئ چې خپل څښتن خدای یې درکوي او هلته واوسېږئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_1.mp3', '', 1761754199, 1761754199),
(45256, 'Deuteronomy 26:2', 'Deuteronomy', 26, 2, 'نو تاسو هر یو باید د هر فصل لومړۍ برخه چې تاسو یې رېبئ په یوې ټوکرۍ کې واچوئ او د خپلو ځانونو سره یې هغه ځای ته یوسئ چې ستاسو څښتن خدای یې د خپل عبادت دپاره غوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_2.mp3', '', 1761754199, 1761754199),
(45257, 'Deuteronomy 26:3', 'Deuteronomy', 26, 3, 'بیا د هغه وخت کاهن ته ورشئ او داسې ورته ووایئ: ‹زه نن خپل څښتن خدای ته دا اقرار کوم چې زه هغه وطن ته ورننوتی یم چې هغه یې زمونږ د نیکونو سره وعده کړې وه چې مونږ ته به یې راکړي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_3.mp3', '', 1761754199, 1761754199),
(45258, 'Deuteronomy 26:4', 'Deuteronomy', 26, 4, 'کاهن به ستاسو څخه ټوکرۍ واخلي او د څښتن خدای د قربانۍ د ځای په مخکې به یې کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_4.mp3', '', 1761754199, 1761754199),
(45259, 'Deuteronomy 26:5', 'Deuteronomy', 26, 5, 'بیا به تاسو د څښتن په حضور کې دا خبرې بیان کړئ: ‹زما نیکه چې د سوریې څخه ؤ یو سرګردانه سړی ؤ. هغه خپله کورنۍ مصر ته بوتله چې هلته واوسیږي. کله چې هغوی هلته لاړل، د هغوی شمېر کم ؤ، خو یو لوی او قدرتمند قوم ورڅخه جوړ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_5.mp3', '', 1761754199, 1761754199),
(45260, 'Deuteronomy 26:6', 'Deuteronomy', 26, 6, 'مصریانو زمونږ سره بد چلند کاوه او مونږ یې دې ته مجبورولو چې د غلامانو په توګه کار وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_6.mp3', '', 1761754199, 1761754199),
(45261, 'Deuteronomy 26:7', 'Deuteronomy', 26, 7, 'بیا مونږ د خپلو نیکونو څښتن خدای ته د مرستې دپاره فریاد وکړ. هغه زمونږ فریاد واورېد او ویې لیدل چې مونږ څومره بې وزلي وو چې مصریانو راباندې ظلم کاوه او مونږ یې مجبورولو چې سخت کار وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_7.mp3', '', 1761754199, 1761754199),
(45262, 'Deuteronomy 26:8', 'Deuteronomy', 26, 8, 'هغه د زورورو معجزو په ښودلو سره مصریان سخت ووېرول او په خپل قوي مټ او ټول قدرت سره یې مونږ د مصر څخه ازاد کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_8.mp3', '', 1761754199, 1761754199),
(45263, 'Deuteronomy 26:9', 'Deuteronomy', 26, 9, 'هغه مونږ دلته راوستلو او دا غني او حاصلخېزه ځمکه یې مونږ ته راکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_9.mp3', '', 1761754199, 1761754199),
(45264, 'Deuteronomy 26:10', 'Deuteronomy', 26, 10, 'نو اوس زه تاته د هغو حاصلاتو لومړنۍ برخه راوړم چې تا څښتن راته راکړي دي.› ټوکرۍ د څښتن په حضور کې کېږدئ او هلته عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_10.mp3', '', 1761754199, 1761754199),
(45265, 'Deuteronomy 26:11', 'Deuteronomy', 26, 11, 'بیا لاړ شئ او د هغو ټولو ښو شیانو په خاطر چې ستاسو څښتن خدای تاسو او ستاسو کورنیو ته درکړي دي جشن ونیسئ. دا یاد ساتئ چې لاویانو او هغه پردیو خلکو ته چې ستاسو په منځ کې اوسیږي، په دې جشن کې بلنه ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_11.mp3', '', 1761754199, 1761754199),
(45266, 'Deuteronomy 26:12', 'Deuteronomy', 26, 12, 'په هر درېم کال د خپلو حاصلاتو لسمه برخه یعنې عشر هغو لاویانو، پردیو خلکو، یتیمانو او کونډو ته چې ستاسو په ښارونو کې اوسیږي ورکوئ، ترڅو هغوی د خوراک دپاره هرڅه ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_12.mp3', '', 1761754199, 1761754199),
(45267, 'Deuteronomy 26:13', 'Deuteronomy', 26, 13, 'بیا څښتن ته داسې ووایئ: ‹ما د خپل کور څخه هغه لسمه برخه چې سپېڅلې ده واخیستله او هغه مې ستا د حکم سره سم لاویانو، پردیو خلکو، یتیمانو او کونډو ته ورکړه. ما ستا د هېڅ هغو حکمونو څخه چې د عشر په هکله دي، سرغړونه نه ده کړې او نه مې هېر کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_13.mp3', '', 1761754199, 1761754199),
(45268, 'Deuteronomy 26:14', 'Deuteronomy', 26, 14, 'ما د غمرازۍ په وخت کې د دې سپېڅلي عشر څخه هېڅ شی نه دی خوړلی. کله چې زه ناپاک وم هغو ته مې لاس نه دی وروړی او نه مې د هغو څخه د مړو په نوم څه ورکړي دي. ای زما څښتنه، ما ستا اطاعت کړی دی او تا چې ماته هر حکم کړی دی هغه مې په ځای کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_14.mp3', '', 1761754199, 1761754199),
(45269, 'Deuteronomy 26:15', 'Deuteronomy', 26, 15, 'ای څښتنه، د خپل سپېڅلي ځای څخه چې په اسمان کې دی، لاندې وګوره او خپل قوم یعنې اسراییلو ته برکت ورکړه. په هغې غني او حاصلخېزې ځمکې کې هم برکت واچوه چې تا مونږ ته د هغې وعدې سره سم راکړې ده چې زمونږ د نیکونو سره دې کړې وه.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_15.mp3', '', 1761754199, 1761754199),
(45270, 'Deuteronomy 26:16', 'Deuteronomy', 26, 16, 'نن تاسو ته خپل څښتن خدای حکم کوي چې د هغه ټولو قوانینو ته غاړه کېږدئ. نو په وفادارۍ سره او د زړه له کومي هغو ته غاړه کېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_16.mp3', '', 1761754199, 1761754199),
(45271, 'Deuteronomy 26:17', 'Deuteronomy', 26, 17, 'نن تاسو اقرار وکړ چې څښتن ستاسو خدای دی. تاسو وعده کړې ده چې د هغه اطاعت به کوئ، د هغه د ټولو قوانینو څخه به پیروي کوئ او د هغه په ټولو حکمونو باندې به عمل کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_17.mp3', '', 1761754199, 1761754199),
(45272, 'Deuteronomy 26:18', 'Deuteronomy', 26, 18, 'څښتن د خپلې وعدې سره سم نن دا اقرار کړی دی چې تاسو د هغه ځانګړی قوم یئ او تاسو ته حکم کوي چې د هغه ټولو قوانینو ته غاړه کېږدئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_18.mp3', '', 1761754199, 1761754199),
(45273, 'Deuteronomy 26:19', 'Deuteronomy', 26, 19, 'څښتن به ستاسو قوم د نورو ټولو قومونو څخه چې هغه پیدا کړي دي، لوی کړي او ستاسو صفت او عزت به کیږي. تاسو به د څښتن د وعدې سره سم د هغه خپل قوم یئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy26_verse_19.mp3', '', 1761754199, 1761754199),
(45274, 'Leviticus 7:1', 'Leviticus', 7, 1, 'د تاوان د نذرانې دپاره چې ډېره سپېڅلې ده، دغه اصول دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_1.mp3', '', 1761754199, 1761754199),
(45275, 'Leviticus 7:2', 'Leviticus', 7, 2, 'د تاوان د نذرانې دپاره دې حیوان په هغه ځای کې حلال شي چې د سوځېدونکې نذرانې دپاره حیوانات حلالیږي او د هغه وینه دې د قربانۍ د ځای په څلورو خواو باندې وشیندل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_2.mp3', '', 1761754199, 1761754199),
(45276, 'Leviticus 7:3', 'Leviticus', 7, 3, 'د هغه ټوله وازګه دې وړاندې شي، لکه لم او هغه وازګه چې په کولمو باندې پرته ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_3.mp3', '', 1761754199, 1761754199),
(45277, 'Leviticus 7:4', 'Leviticus', 7, 4, 'پښتورګي د هغې وازګې سره چې دپاسه ورباندې پرته وي او د اینې ډېره ښه برخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_4.mp3', '', 1761754199, 1761754199),
(45278, 'Leviticus 7:5', 'Leviticus', 7, 5, 'کاهن به هغه ټول د قربانۍ په ځای باندې د داسې نذرانې په توګه وسوځوي چې څښتن ته تیاریږي. دا د تاوان نذرانه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_5.mp3', '', 1761754199, 1761754199),
(45279, 'Leviticus 7:6', 'Leviticus', 7, 6, 'د کاهن د کورنۍ هر نارینه کولای شي چې هغه وخوري، خو هغه باید په یو سپېڅلي ځای کې وخوړل شي، ځکه چې ډېره سپېڅلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_6.mp3', '', 1761754199, 1761754199),
(45280, 'Leviticus 7:7', 'Leviticus', 7, 7, 'د ګناه د نذرانې او د تاوان د نذرانې دواړو دپاره یوشان قانون عملي کیږي: غوښه د کاهن ده یعنې د هغه چا دپاره ده چې د دې نذرانو په وسیله کفاره ادا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_7.mp3', '', 1761754199, 1761754199),
(45281, 'Leviticus 7:8', 'Leviticus', 7, 8, 'د سوځېدونکې نذرانې د حیوان پوستکی د هغه کاهن دی چې قرباني وړاندې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_8.mp3', '', 1761754199, 1761754199),
(45282, 'Leviticus 7:9', 'Leviticus', 7, 9, 'د غلې دانې هره نذرانه چې په تنور کې یا په ارکاره یا په تبۍ باندې پخیږي، هغه د کاهن یعنې د هغه چا ده چې هغه نذرانه خدای ته وړاندې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_9.mp3', '', 1761754199, 1761754199),
(45283, 'Leviticus 7:10', 'Leviticus', 7, 10, 'خو د خامې غلې دانې ټولې نذرانې که د تېلو سره ګډې وي یا وچې وي، هغه د هارون د زامنو یعنې د ټولو کاهنانو دي او باید د هغوی ترمنځ په مساوي ډول ووېشل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_10.mp3', '', 1761754199, 1761754199),
(45284, 'Leviticus 7:11', 'Leviticus', 7, 11, 'د سلامتۍ د هغو نذرانو دپاره چې یو کس یې څښتن ته وړاندې کوي، دغه اصول دي:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_11.mp3', '', 1761754199, 1761754199),
(45285, 'Leviticus 7:12', 'Leviticus', 7, 12, 'که چېرې هغه کس دا نذرانه خدای ته د شکرانې د نذرانې په توګه وړاندې کوي، هغه به د هغه حیوان سره چې قرباني کیږي، د یوې فطیرې ډوډۍ نذرانه وړاندې کوي: هغه دې د ښو اوړو څخه درې ډوله ډوډۍ پخې کړي چې دوه یې د زیتونو په تېلو کې پخې شوې وي او یوه دې نرۍ ډوډۍ وي چې تېل ورباندې موښل شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_12.mp3', '', 1761754199, 1761754199),
(45286, 'Leviticus 7:13', 'Leviticus', 7, 13, 'هغه کس دې څو خمیره ډوډۍ هم وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_13.mp3', '', 1761754199, 1761754199),
(45287, 'Leviticus 7:14', 'Leviticus', 7, 14, 'د هر ډول ډوډۍ څخه دې یوه یوه ډوډۍ د یوې ځانګړې اعانې په توګه څښتن ته وړاندې کړي. دا د هغه کاهن دپاره دي چې د حیوان وینه اخلي او د قربانۍ په ځای باندې یې شیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_14.mp3', '', 1761754199, 1761754199),
(45288, 'Leviticus 7:15', 'Leviticus', 7, 15, 'د دغې سلامتۍ نذرانې د حیوان غوښه باید په هماغه ورځ چې هغه قرباني کیږي، وخوړل شي. د هغې څخه دې تر بل سهاره پورې هېڅ شی پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_15.mp3', '', 1761754199, 1761754199),
(45289, 'Leviticus 7:16', 'Leviticus', 7, 16, 'که چېرې یو کس د خپلې خوښې نذرانه یا د نذر ورکولو په توګه د سلامتۍ نذرانه راوړي، نو د قربانۍ غوښه دې په هماغه ورځ چې وړاندې کیږي، وخوړل شي. خو څه چې پاتې شي، هغه دې په راتلونکې ورځ وخوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_16.mp3', '', 1761754199, 1761754199),
(45290, 'Leviticus 7:17', 'Leviticus', 7, 17, 'کومه غوښه چې د قربانۍ څخه تر درېمې ورځې پورې پاتې کیږي، باید وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_17.mp3', '', 1761754199, 1761754199),
(45291, 'Leviticus 7:18', 'Leviticus', 7, 18, 'که چېرې د سلامتۍ د نذرانې کومه غوښه په درېمه ورځ وخوړل شي، خدای به د هغه کس نذرانه قبوله نه کړي. دا به د هغه په نذرانه کې حساب نه شي، بلکې هغه به ناپاکه وګڼل شي. که څوک د هغې څخه لږه وخوري، نو د خپلو بدو سزا به وویني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_18.mp3', '', 1761754199, 1761754199),
(45292, 'Leviticus 7:19', 'Leviticus', 7, 19, 'که چېرې دا غوښه په یو ناپاکه شي باندې ولګیږي هغه باید ونه خوړل شي، بلکې باید وسوځول شي. که څوک پاک وي، هغه کولای شي چې دا غوښه وخوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_19.mp3', '', 1761754199, 1761754199),
(45293, 'Leviticus 7:20', 'Leviticus', 7, 20, 'خو که چېرې څوک ناپاک وي او د سلامتۍ د نذرانې هغه غوښه چې څښتن ته وړاندې کیږي وخوري، نو هغه کس باید د خدای د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_20.mp3', '', 1761754199, 1761754199),
(45294, 'Leviticus 7:21', 'Leviticus', 7, 21, 'که چېرې یو کس یو ناپاکه شي ته لاس وروړي، که هغه انساني ناپاکي وي یا په مذهبي توګه یو ناپاکه حیوان وي او بیا د سلامتۍ د نذرانې هغه غوښه وخوري، نو هغه کس باید د خدای د قوم څخه وشړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_21.mp3', '', 1761754199, 1761754199),
(45295, 'Leviticus 7:22', 'Leviticus', 7, 22, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_22.mp3', '', 1761754199, 1761754199),
(45296, 'Leviticus 7:23', 'Leviticus', 7, 23, '«د اسراییلو قوم ته ووایه چې د غویانو، وریو او وزو وازګه مه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_23.mp3', '', 1761754199, 1761754199),
(45297, 'Leviticus 7:24', 'Leviticus', 7, 24, 'د یو حیوان وازګه چې په خپل مرګ مړ شوی وي یا یو وحشي حیوان وژلی وي، باید په هېڅ ونه خوړل شي، خو د هغه څخه د کوم بل مقصد دپاره کار اخیستلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_24.mp3', '', 1761754199, 1761754199),
(45298, 'Leviticus 7:25', 'Leviticus', 7, 25, 'هرڅوک چې د یو داسې حیوان وازګه وخوري چې کېدای شي د یوې نذرانې په توګه څښتن ته په اور باندې تیاره شي، هغه باید د خدای د قوم څخه وشړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_25.mp3', '', 1761754199, 1761754199),
(45299, 'Leviticus 7:26', 'Leviticus', 7, 26, 'هر چېرته چې اوسېږئ، باید د مرغۍ یا د حیوان وینه ونه خورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_26.mp3', '', 1761754199, 1761754199),
(45300, 'Leviticus 7:27', 'Leviticus', 7, 27, 'هرڅوک چې دا قانون مات کړي باید د خدای د قوم څخه وشړل شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_27.mp3', '', 1761754199, 1761754199),
(45301, 'Leviticus 7:28', 'Leviticus', 7, 28, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_28.mp3', '', 1761754199, 1761754199),
(45302, 'Leviticus 7:29', 'Leviticus', 7, 29, '«اسراییلیانو ته ووایه چې هرڅوک چې د سلامتۍ نذرانه وړاندې کوي، هغه دې څښتن ته د هغې یوه برخه د ځانګړي سوغات په توګه راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_29.mp3', '', 1761754199, 1761754199),
(45303, 'Leviticus 7:30', 'Leviticus', 7, 30, 'هغه دې په خپل لاس هغه نذرانه راوړي چې څښتن ته په اور باندې تیاریږي. هغه دې د حیوان سینه د وازګې سره پورته ونیسي، ترڅو دا وښایي چې هغه ماته وقف شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_30.mp3', '', 1761754199, 1761754199),
(45304, 'Leviticus 7:31', 'Leviticus', 7, 31, 'کاهن به وازګه د قربانۍ په ځای باندې وسوځوي، خو سینه به د کاهنانو شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_31.mp3', '', 1761754199, 1761754199),
(45305, 'Leviticus 7:32', 'Leviticus', 7, 32, 'همدارنګه تاسو باید د خپلې سلامتۍ د نذرانې د حیوان شاتنۍ ښي پښه کاهن ته د ځانګړې اعانې په توګه ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_32.mp3', '', 1761754199, 1761754199),
(45306, 'Leviticus 7:33', 'Leviticus', 7, 33, 'کاهن چې د سلامتۍ د نذرانې وینه او وازګه وړاندې کوي، هغه به شاتنۍ ښي پښه د خپلې برخې په توګه واخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_33.mp3', '', 1761754199, 1761754199),
(45307, 'Leviticus 7:34', 'Leviticus', 7, 34, 'د حیوان سینه یو ځانګړی سوغات دی او شاتنۍ ښي پښه یوه ځانګړې اعانه ده چې څښتن د اسراییلو د خلکو څخه اخیستې او کاهنانو ته یې ورکړې ده. په دې خاطر د اسراییلو خلک باید هغه د تل دپاره کاهنانو ته ورکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_34.mp3', '', 1761754199, 1761754199),
(45308, 'Leviticus 7:35', 'Leviticus', 7, 35, 'دا د هغې نذرانې برخه ده چې څښتن ته په اور باندې تیاریږي چې هارون او د هغه زامنو ته په هغه ورځ ورکړل شوه چې هغوی د کاهنانو په توګه د څښتن د خدمت دپاره وټاکل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_35.mp3', '', 1761754199, 1761754199),
(45309, 'Leviticus 7:36', 'Leviticus', 7, 36, 'په هغه ورځ څښتن د اسراییلو قوم ته امر وکړ چې هغوی ته د نذرانې دا برخه ورکړي. دا یو داسې قانون دی چې د اسراییلو قوم باید د تل دپاره ورته غاړه کېږدي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_36.mp3', '', 1761754199, 1761754199),
(45310, 'Leviticus 7:37', 'Leviticus', 7, 37, 'دا اصول د دغو نذرانو دپاره دي لکه سوځېدونکې نذرانې، د غلې دانې نذرانې، د ګناه نذرانې، د تاوان نذرانې، د ټاکنې نذرانې او د سلامتۍ نذرانې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus7_verse_37.mp3', '', 1761754199, 1761754199);